101	fn resolve_script_language(
102	    candidate: &EmbedCandidate,
103	    file_source: &DocumentFileSource,
104	) -> Option<GuestLanguage> {
105	    let html_source = file_source.to_html_file_source()?;
106	
107	    // Check script type attribute first
108	    if let Some(type_value) = candidate.attribute("type") {
109	        let script_type = ScriptType::from_type_value(type_value.text());
110	        if script_type.is_json() {
111	            return Some(GuestLanguage::Json);
112	        }
113	        if !script_type.is_javascript() {
114	            return None; // unsupported type (e.g. text/x-handlebars-template)
115	        }
116	    }
117	
118	    // Framework-specific resolution
119	    if html_source.is_vue() || html_source.is_svelte() {
120	        // Check lang attribute
121	        if candidate.has_attribute_value("lang", "ts") {
122	            Some(GuestLanguage::Ts)
123	        } else if candidate.has_attribute_value("lang", "tsx") {
124	            Some(GuestLanguage::Tsx)
125	        } else if candidate.has_attribute_value("lang", "jsx") {
126	            Some(GuestLanguage::Jsx)
127	        } else {
128	            Some(GuestLanguage::JsModule)
129	        }
130	    } else if html_source.is_astro() {
131	        // Astro <script> tags (not frontmatter) default to TypeScript
132	        Some(GuestLanguage::Ts)
133	    } else {
134	        // Plain HTML
135	        if candidate.has_attribute_value("type", "module") {
136	            Some(GuestLanguage::JsModule)
137	        } else {
138	            Some(GuestLanguage::JsScript)
139	        }
140	    }
141	}
